import json
import requests
import sys
from typing import Dict, List, Any

def evaluate_expression(expr: str, item: Dict[str, Any]) -> Any:
    try:
        return eval(expr, {'__builtins__': None}, item)
    except Exception as e:
        raise ValueError(f"Error evaluating expression '{expr}': {e}")

def process_item(item_config: Dict[str, Any], response_data: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    fields = item_config['fields']
    result = []
    for item in response_data:
        processed_item = {}
        for field_name, expr in fields.items():
            try:
                processed_item[field_name] = evaluate_expression(expr, item)
            except ValueError as e:
                raise ValueError(f"Failed to process field '{field_name}': {e}")
        result.append(processed_item)
    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python api_summary.py <config_file.json> <output_file.json>", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    output_path = sys.argv[2]

    try:
        with open(config_path, 'r') as config_file:
            config = json.load(config_file)
    except json.JSONDecodeError as e:
        print(f"Error parsing config file: {e}", file=sys.stderr)
        sys.exit(1)

    output_data = {}

    for item_config in config['items']:
        source = item_config['source']
        try:
            response = requests.get(source)
            response.raise_for_status()
            response_data = response.json()
        except requests.RequestException as e:
            print(f"Error fetching {source}: {e}", file=sys.stderr)
            continue

        processed_data = process_item(item_config, response_data)
        output_data[source] = processed_data

    try:
        with open(output_path, 'w') as output_file:
            json.dump(output_data, output_file, indent=2)
    except IOError as e:
        print(f"Error writing output file: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import json
