import sys
from typing import Dict, List, Any

def process_url(url: str, config: Dict[str, Dict[str, str]]) -> List[Dict[str, Any]]:
    try:
        response = requests.get(url)
        response.raise_for_status()
        data = response.json()
        result = []
        for item in data:
            processed_item = {}
            for field, expr in config[url].items():
                try:
                    evaluated = eval(expr, {}, item)
                    processed_item[field] = evaluated
                except Exception as e:
                    print(f"Error evaluating expression '{expr}' for field '{field}': {e}", file=sys.stderr)
                    processed_item[field] = None
            result.append(processed_item)
        return result
    except Exception as e:
        print(f"Error processing URL '{url}': {e}", file=sys.stderr)
