import json
import sys
import requests
from typing import Dict, List, Any

def evaluate_expression(item: Dict[str, Any], expr: str) -> int:
    try:
        # Handle string subscripts (e.g., item['count'])
        if "'" in expr:
            key = expr.split("'")[1]
            return item[key]
        else:
            return eval(expr)
    except Exception as e:
        raise ValueError(f"Error evaluating expression '{expr}': {e}")

def process_url(url: str, config: Dict[str, str], response: List[Dict[str, Any]]) -> List[int]:
    expr = config[url]
    return [evaluate_expression(item, expr) for item in response]

def main():
    if len(sys.argv) != 3:
        print("Usage: python api_summary.py <config_file.json> <output_file.json>", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    output_path = sys.argv[2]

    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except Exception as e:
        print(f"Error reading config file: {e}", file=sys.stderr)
        sys.exit(1)

    output_data = {}

    for url, expr in config.items():
        try:
            response = requests.get(url)
            response.raise_for_status()
            response_data = response.json()
            computed_values = process_url(url, config, response_data)
            output_data[url] = computed_values
        except Exception as e:
            print(f"Error processing URL {url}: {e}", file=sys.stderr)
            continue

    try:
        with open(output_path, 'w') as f:
            json.dump(output_data, f, indent=2)
    except Exception as e:
        print(f"Error writing output file: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
